class CsqttGenerationChecks {
 static int count;static MainWindow main;static Application app;static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static string root;
 static void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static void Reject(Action action,string name){bool rejected=false;try{action();}catch(FormatException){rejected=true;}Check(rejected,name);}
 static string Plain="csqtt://connect?v=2&host=192.0.2.1&peer=56000&password=fixture-only&hashes="+new string('A',43);
 static ServerNode Node(string generation){var node=Links.Read(Plain).Single();node.CsqttGeneration=generation;return node;}
 static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}
 static void Wait(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(30);while(!done()&&DateTime.UtcNow<end){Pump();Thread.Sleep(5);}if(!done())throw new Exception("Timeout");}
 static IEnumerable<T> All<T>(DependencyObject r)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(r);i++){var child=VisualTreeHelper.GetChild(r,i);if(child is T)yield return (T)child;foreach(var value in All<T>(child))yield return value;}}
 static object Call(string name,params object[] args){return typeof(MainWindow).GetMethod(name,F).Invoke(main,args);}
 [STAThread]static int Main(string[] args){try{
  root=Path.GetFullPath(args[0]);if(Directory.Exists(root))throw new Exception("Fresh fixture required");Directory.CreateDirectory(root);Check(CsqttGenerations.All.Length==4,"four pinned native protocol generations, no duplicate Rebirth engine");Check(CsqttGenerations.NeedsChoice(Links.Read(Plain).Single()),"legacy v=2 does not identify a wire generation");
  foreach(var g in CsqttGenerations.All){var node=Node(g.Id);Check(CsqttGenerations.For(node).Id==g.Id&&CsqttGenerations.Get(g.Id).Executable==g.Executable,"generation-to-engine exact mapping "+g.Id);var copy=Links.Read(CsqttGenerations.Share(node)).Single();Check(CsqttGenerations.For(copy).Id==g.Id,"shared plaintext link retains generation "+g.Id);}
  var sealedLink=Csqtt25Link.Seal(Plain);var sealedNode=Links.Read(sealedLink).Single();Check(!CsqttGenerations.NeedsChoice(sealedNode)&&CsqttGenerations.For(sealedNode).Id=="2.5","authenticated sealed link selects 2.5 / Rebirth without trial connection");sealedNode.CsqttGeneration="2.0";Reject(()=>CsqttGenerations.For(sealedNode),"sealed 2.5 cannot be forced into old runtime");Check(CsqttGenerations.Normalize("rebirth")=="2.5"&&CsqttGenerations.Normalize("2.5.0-legacy")=="2.5","Rebirth aliases share 2.5 generation");
  var rust=TurnProfile.Parse("csqtt://GNANVH0fhD6MisDFiWP_P0Bm_FHr-frawgfwur3Zx4ipjJx8gk-M6ZZbnDr_2clwPmzO-QS8AkiHLaMXyYO1RHyPeehXPqTc6jJi_iw72fRQJ9AR918ne5XsBRg");Check(rust.Host=="1.2.3.4"&&rust.Port==46000&&rust.Csqtt25,"official Rust encrypted fixture interoperates");var padded="csqtt://"+sealedLink.Substring(8).Replace('-','+').Replace('_','/');padded=padded.PadRight(8+(padded.Length-8+3)/4*4,'=');Check(TurnProfile.Parse(padded).Password=="fixture-only","standard base64 and padding envelopes imported");
  Check(TurnProfile.Parse("csqtt://secret@192.0.2.1:46000").Password=="secret","legacy authority link imported");Check(TurnProfile.Parse("csqtt://connect?v=2host=192.0.2.1peer=46000password=secret").Port==46000,"legacy concatenated query imported");Check(TurnProfile.Parse("csqtt://connect?v=2&host=192.0.2.1&peer=46000").Password=="","owner link imported without inventing a password");Check(TurnProfile.Parse(Plain.Replace(new string('A',43),"abcdefghijklmnop%2Bp")).Hashes.Single()=="abcdefghijklmnop+p","encoded plus inside a hash is not a hash separator");
  Reject(()=>TurnProfile.Parse(Plain+"&password=other"),"duplicate parameters rejected");Reject(()=>TurnProfile.Parse(Plain+"&token=fixture-token"),"ambiguous token plus explicit hashes rejected");Reject(()=>CsqttGenerations.Hint(Plain+"&mcrf_generation=9"),"unknown generation rejected, never guessed");string tampered=sealedLink.Substring(0,24)+(sealedLink[24]=='A'?"B":"A")+sealedLink.Substring(25);Reject(()=>TurnProfile.Parse(tampered),"tampered sealed link rejected");
  var store=new StateStore(Path.Combine(root,"model"));var state=new ClientState();SubscriptionMerge.Apply(state,new List<ServerNode>{Node("2.0")},null);SubscriptionMerge.Apply(state,new List<ServerNode>{Node("2.1.9")},null);Check(state.Servers.Count==2,"same endpoint/link can coexist for incompatible generations");store.Save(state);Check(store.Load().Servers.Select(n=>n.CsqttGeneration).OrderBy(x=>x).SequenceEqual(new[]{"2.0","2.1.9"}),"generation survives encrypted state persistence");var old=Node("2.0");old.Source="https://example.invalid/sub";var incoming=Links.Read(Plain).Single();SubscriptionMerge.InheritCsqttGenerations(new[]{incoming},new[]{old},old.Source);Check(incoming.CsqttGeneration=="2.0","subscription refresh retains explicit previous generation");
  var core=new NetworkCore(new StateStore(Path.Combine(root,"packages")));Check(core.Engines.Packages.Count()==7,"catalogue exposes four independent CSQTT downloads");var packages=core.Engines.Packages.ToArray();var oldCatalog=new EngineCatalog{Version=1,Engines=packages.Where(p=>!new[]{"csqtt20","csqtt215","csqtt25"}.Contains(p.Id)).ToList()};var merged=OptionalEngines.MergeEmbeddedRequirements(oldCatalog,new EngineCatalog{Version=1,Engines=packages.ToList()});Check(merged.Engines.Count==7&&merged.Engines.Contains(oldCatalog.Engines.First()),"old active catalogue gains generations without losing unrelated pins");
  foreach(var g in CsqttGenerations.All){if(g.Id!="2.1.9")continue;var p=core.Engines.Package(g.Package);string staging=Path.Combine(core.Engines.StorageRoot,".download-fixture-"+g.Package);Directory.CreateDirectory(staging);core.Engines.InstallArchive(p,Path.Combine(args[1],Path.GetFileName(new Uri(p.Url).LocalPath)),staging,CancellationToken.None);}
  Check(core.CSQTTExecutableFor(Node("2.1.9"))!=null&&core.CSQTTExecutableFor(Node("2.0"))==null&&core.CSQTTExecutableFor(Node("2.1.5"))==null&&core.CSQTTExecutableFor(Node("2.5"))==null,"only installed generation is selected; no fallback to incompatible engine");
  foreach(var g in CsqttGenerations.All.Where(g=>g.Id!="2.1.9")){var p=core.Engines.Package(g.Package);string staging=Path.Combine(core.Engines.StorageRoot,".download-fixture-"+g.Package);Directory.CreateDirectory(staging);core.Engines.InstallArchive(p,Path.Combine(args[1],Path.GetFileName(new Uri(p.Url).LocalPath)),staging,CancellationToken.None);Check(Path.GetFileName(core.CSQTTExecutableFor(Node(g.Id)))==g.Executable,"verified archive installs exact executable "+g.Id);}
  var resources=typeof(NetworkCore).Assembly.GetManifestResourceNames();Check(!resources.Any(n=>n.Contains("csqtt20-client")||n.Contains("csqtt215-client")||n.Contains("csqtt25-client")||n.Contains("csqtt-client")),"no optional CSQTT binaries embedded in application");
  var program=typeof(MainWindow).Assembly.GetType("Mcrf.Wpf.Program");app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};program.GetMethod("LoadTheme",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{app});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());main=new MainWindow(new[]{"--data",Path.Combine(root,"ui")}){ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual,Left=-10000,Top=-10000};main.Show();Wait(()=>typeof(MainWindow).GetField("session",F).GetValue(main)!=null);((DispatcherTimer)typeof(MainWindow).GetField("health",F).GetValue(main)).Stop();var session=(ClientSession)typeof(MainWindow).GetField("session",F).GetValue(main);typeof(ClientSession).GetField("catalogTask",F).SetValue(session,Task.FromResult(new ZapretStrategy[0]));var choice=Links.Read(Plain).Single();Exception failure=null;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(s,e)=>{var w=app.Windows.Cast<Window>().FirstOrDefault(x=>x!=main&&x.Title=="Поколение CSQTT");if(w==null)return;timer.Stop();try{w.Left=-10000;w.Top=-10000;var select=All<ComboBox>(w).Single(c=>c.Name=="csqttImportGeneration");select.SelectedIndex=1;All<Button>(w).Single(b=>Convert.ToString(b.Content)=="Продолжить").RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));}catch(Exception ex){failure=ex;w.Close();}};timer.Start();bool accepted=(bool)Call("ChooseCsqttGenerations",(object)new[]{choice});timer.Stop();if(failure!=null)throw failure;Check(accepted&&choice.CsqttGeneration=="2.0","actual import dialog chooses old generation before any connection");Check(!session.Core.Running,"import and archive checks did not connect VK or start VPN");main.Close();Wait(()=>!main.IsVisible);app.Shutdown();Console.WriteLine("RESULT "+count+" checks PASS");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);if(main!=null)main.Close();return 1;}}
}
